<?php
namespace App\Controllers; use App\Models\StudentModel; use App\Models\VerificationAssistanceRequestModel; use App\Services\AssistanceDocumentStorage; use CodeIgniter\Exceptions\PageNotFoundException;
final class VerificationAssistanceAdminController extends BaseController { protected $helpers=['form','url']; public function index():string{$m=new VerificationAssistanceRequestModel();$status=(string)$this->request->getGet('status');if(in_array($status,['pending','under_review','resolved','rejected'],true))$m->where('status',$status);return view('assistance/index',['title'=>'Verification requests','requests'=>$m->orderBy('created_at','DESC')->paginate(20),'pager'=>$m->pager,'status'=>$status]);}public function show(int $id):string{$r=$this->request($id);return view('assistance/show',['title'=>'Verification request #'.$id,'request'=>$r,'student'=>(new StudentModel())->where('student_id',$r['student_id'])->first(),'audits'=>\Config\Database::connect()->table('verification_assistance_audit_logs')->where('request_id',$id)->orderBy('created_at','DESC')->get()->getResultArray()]);}public function update(int $id){$r=$this->request($id);$status=$this->request->getPost('status');$notes=$this->request->getPost('review_notes');if(!is_string($status)||!in_array($status,['pending','under_review','resolved','rejected'],true)||!is_string($notes)||mb_strlen($notes)>4000)return redirect()->to(site_url('admin/verification-requests/'.$id))->with('error','Invalid review update.');(new VerificationAssistanceRequestModel())->update($id,['status'=>$status,'review_notes'=>trim($notes),'reviewed_by'=>(int)session()->get('admin_id'),'reviewed_at'=>gmdate('Y-m-d H:i:s')]);\Config\Database::connect()->table('verification_assistance_audit_logs')->insert(['request_id'=>$id,'admin_id'=>(int)session()->get('admin_id'),'action'=>'status_'.$status,'notes'=>trim($notes)?:null,'created_at'=>gmdate('Y-m-d H:i:s')]);return redirect()->to(site_url('admin/verification-requests/'.$id))->with('success','Review updated.');}public function document(int $id){$r=$this->request($id);$path=(new AssistanceDocumentStorage())->path($r['document_stored_name']);return $this->response->download($path,null)->setFileName($r['document_name']);}private function request(int $id):array{$r=(new VerificationAssistanceRequestModel())->find($id);if(!$r)throw PageNotFoundException::forPageNotFound();return $r;}}
